-- 📚 꼭집 주거 사전 — 총자산 2.45억 · 자동차 4,542만 · 영구임대 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.1초 · 결과:
-- {"n": 25, "by_std": {"매입임대": 3, "영구임대": 22}, "all_asset_anns": 203, "ex": ["2015122300020874", "2015122300020868", "2015122300020866", "2015122300020865"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('n',(select count(distinct announcement_id) from e where asset_limit=245000000 and car_limit=45420000),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit=245000000 and car_limit=45420000 group by 1)q),'all_asset_anns',(select count(distinct announcement_id) from e where asset_limit is not null),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=245000000 and car_limit=45420000 order by 1 desc limit 4)q))j;
